:root {
  /* Colors */
  --color-carbon-canvas: #0a0a0a;
  --color-iron-surface: #262626;
  --color-graphite-tile: #29292e;
  --color-ink: #000000;
  --color-dove-caption: #666666;
  --color-pewter-body: #a1a1a1;
  --color-fog-headline: #e5e5e5;
  --color-paper-action: #fcfcfc;
  --color-slate-hairline: #393939;
  --color-ash-ring: #7777774d;
  --color-ember-link: #ff8833;
  --color-sunbeam-halo: #ffb931;

  /* Typography — Font Families */
  --font-matter-font: "matterFont", "Geist", "Inter Display", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 10px;
  --leading-small: 2;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1.33;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.43;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.33;
  --tracking-body-lg: 0px;
  --text-subheading: 20px;
  --leading-subheading: 1.4;
  --tracking-subheading: 0px;
  --text-heading-sm: 24px;
  --leading-heading-sm: 1.17;
  --tracking-heading-sm: 0px;
  --text-heading: 36px;
  --leading-heading: 1.11;
  --tracking-heading: 0px;
  --text-display: 60px;
  --leading-display: 1;
  --tracking-display: -1.5px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-48: 48px;
  --spacing-56: 56px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-120: 120px;
  --spacing-128: 128px;

  /* Layout */
  --layout-max-width: 1152px;
  --layout-section-gap: 120px;
  --layout-card-padding: 16px;
  --layout-element-gap: 8px;
  --layout-nav-height: 74px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 10px;
  --radius-xl: 12px;
  --radius-2xl: 20px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-inner-tiles: 4px;
  --radius-cards: 8px;
  --radius-nav: 8px;
  --radius-small-elements: 10px;
  --radius-sections: 12px;
  --radius-buttons: 20px;
  --radius-pills: 9999px;
  --radius-tags: 9999px;

  /* Shadows */
  --shadow-subtle: 0px 1px 3px 0px rgba(0, 0, 0, 0.1), 0px 1px 2px -1px rgba(0, 0, 0, 0.1);
  --shadow-subtle-2: inset 0px 0px 2px 2px rgba(101, 129, 128, 0.15), inset 0px 0px 4px 4px rgba(32, 47, 46, 0.15);
  --shadow-sm: 0px 4px 4px 0px rgba(0, 0, 0, 0.25);
  --shadow-sm-2: inset 0px 1px 0px 0px #ffffff, inset 0px -2px 6px 0px rgba(0, 0, 0, 0.1);
  --shadow-md: 0px 8px 10px 0px rgba(0, 0, 0, 0.3);
  --shadow-lg: 0px 0px 8px 8px rgba(0, 0, 0, 0.5);

  /* Surfaces */
  --surface-carbon-canvas: #0a0a0a;
  --surface-iron-surface: #262626;
  --surface-graphite-tile: #29292e;
  --surface-ash-ring: #7777774d;
  --surface-paper-action: #fcfcfc;
}

